// v[0] is an lvalue expression, so decltype infers a reference
std::vector<int> v{100};
decltype(v[0]) ref_to_first_element = v[0]; // Type is int&

// x is a name, so decltype infers its declared type
int x = 0;
decltype(x) x_val = x; // Type is int

// (x) is an lvalue expression, so decltype infers a reference
decltype((x)) x_ref = x; // Type is int&
